#!/usr/bin/env python3
from pathlib import Path
import runpy

try:
    runpy.run_path('tools/patch_subscription_v2_once.py', run_name='__main__')
except RuntimeError as ex:
    if 'settings subscription markup anchor missing' not in str(ex):raise

p=Path('web/settings-v2.js');s=p.read_text()
start=s.index('function subscription(d){');end=s.index('function ipguard(d){',start)
new_func="""function subscription(d){const s=d.subscription;return `<form class="sv2-grid" data-sv2-form="subscription">${card(L('Subscription service','سرویس اشتراک'),L('Only formats actually generated by DARK are exposed.','فقط فرمت‌هایی که واقعاً توسط DARK ساخته می‌شوند نمایش داده می‌شوند.'),`<div class="sv2-span-2">${toggle(L('Enable subscription endpoint','فعال‌سازی لینک اشتراک'),'enabled',s.enabled!==false)}</div><div class="sv2-form-grid"><label class="sv2-field"><span>${L('Default format','فرمت پیش‌فرض')}</span>${segment('default_format',s.default_format||'base64',[['base64','Base64'],['raw','Raw'],['clash','Clash / Mihomo'],['json','DARK JSON']])}</label>${field(L('Profile update interval (hours)','بازه آپدیت پروفایل (ساعت)'),'profile_update_interval_hours',s.profile_update_interval_hours||6,'number','', 'min="1" max="168" required')}<div class="sv2-span-2">${toggle(L('Auto detect Clash / Mihomo','تشخیص خودکار Clash / Mihomo'),'auto_detect',s.auto_detect!==false,L('Known Clash/Mihomo user agents receive Clash output automatically.','User-Agentهای شناخته‌شده Clash/Mihomo خروجی Clash می‌گیرند.'))}</div></div>`)}${card(L('Profile identity','هویت پروفایل'),L('Metadata returned with every subscription response.','متادیتایی که همراه هر پاسخ اشتراک برمی‌گردد.'),`<div class="sv2-form-grid">${field(L('Profile title','عنوان پروفایل'),'profile_title',s.profile_title||'DARK XRAY','text','', 'maxlength="120"')}${field(L('Profile page URL','لینک صفحه پروفایل'),'profile_url',s.profile_url||'','url','', 'dir="ltr"')}${field(L('Support URL','لینک پشتیبانی'),'support_url',s.support_url||'','url','', 'dir="ltr"')}<label class="sv2-field sv2-span-2"><span>${L('Announcement','اعلان')}</span><textarea class="field-input" name="announce" maxlength="2000" rows="3">${esc(s.announce||'')}</textarea></label></div>`)}${card(L('Link naming','نام‌گذاری لینک‌ها'),L('Variables: {remark}, {email}, {protocol}.','متغیرها: {remark}، {email}، {protocol}.'),`<div class="sv2-form-grid">${field(L('Remark template','قالب نام'),'remark_template',s.remark_template||'{remark} | {email}','text','', 'maxlength="200"')}</div>`)}${saveButton()}</form>`;}
"""
s=s[:start]+new_func+s[end:]
start=s.index('async function saveSubscription(form){');end=s.index('async function saveGuard(form){',start)
new_save="""async function saveSubscription(form){const s={...(SV.data.subscription||{})};s.enabled=formValue(form,'enabled')==='true';s.default_format=formValue(form,'default_format');s.auto_detect=formValue(form,'auto_detect')==='true';s.profile_update_interval_hours=n(formValue(form,'profile_update_interval_hours'),6);s.remark_template=formValue(form,'remark_template');s.support_url=formValue(form,'support_url').trim();s.profile_title=formValue(form,'profile_title').trim();s.profile_url=formValue(form,'profile_url').trim();s.announce=formValue(form,'announce').trim();await api('/api/settings/subscription','PUT',{value:s});toast(L('Subscription settings saved.','تنظیمات اشتراک ذخیره شد.'));}
"""
s=s[:start]+new_save+s[end:];p.write_text(s)

p=Path('tests/run-tests.sh');s=p.read_text();needle="python -m pytest tests/test_clients_v2.py -q --junitxml=qa/junit/clients-v2.xml\n"
if 'test_subscription_v2.py' not in s:s=s.replace(needle,needle+"python -m pytest tests/test_subscription_v2.py -q --junitxml=qa/junit/subscription-v2.xml\n")
p.write_text(s)
Path('tests/test_subscription_v2.py').write_text('''import base64,json,pytest\nfrom fastapi.testclient import TestClient\nfrom auth import Auth\nfrom core import Config,CoreEngine\nfrom dark_policy import Store,Actor\nfrom manager import Manager\nfrom server import make_app\nOWNER=Actor("dark","owner",{})\nIB={"remark":"SUBV2","listen":"127.0.0.1","port":19701,"protocol":"vless","enable":True,"tag":"subv2","settings":{"decryption":"none"},"streamSettings":{"network":"tcp","security":"none"},"sniffing":{}}\n@pytest.fixture\ndef env(tmp_path):\n store=Store(tmp_path/"d.sqlite3");cfg=Config(xray_binary=str(tmp_path/"missing"),xray_assets=str(tmp_path),public_address="vpn.test",test_engine=True);eng=CoreEngine(cfg,store,tmp_path/"runtime");m=Manager(store,eng);auth=Auth(store,tmp_path/"secret.key");auth.bootstrap("dark","Test!OnlyPassword123");m.owner_put(OWNER,"dark",name="DARK",allowed=[])\n with TestClient(make_app(m,auth,background=False),base_url=cfg.public_origin) as c:\n  r=c.post("/api/auth/login",json={"username":"dark","password":"Test!OnlyPassword123"});c.headers["X-Dark-CSRF"]=r.json()["csrf"];ib=c.post("/api/inbounds",json=IB).json();u=c.post("/api/clients",json={"owner":"dark","client":{"email":"sub-v2"},"inboundIds":[ib["id"]]}).json();yield c,u["subscription_url"]\n store.close()\n\ndef test_formats_and_headers(env):\n c,url=env;s=c.get("/api/settings/subscription").json()["value"];s.update(default_format="raw",auto_detect=True,profile_title="DARK TEST",profile_url="https://profile.test",announce="hello");assert c.put("/api/settings/subscription",json={"value":s}).status_code==200\n raw=c.get(url);assert raw.status_code==200 and raw.content.startswith(b"vless://") and raw.headers["profile-title"]=="DARK TEST"\n b64=c.get(url+"?format=base64");assert base64.b64decode(b64.content).startswith(b"vless://")\n js=c.get(url+"?format=json");doc=js.json();assert doc["title"]=="DARK TEST" and doc["links"][0]["uri"].startswith("vless://")\n clash=c.get(url+"?format=clash");assert clash.status_code==200 and 'DARK AUTO' in clash.text and 'vless' in clash.text\n\ndef test_clash_user_agent_auto_detect(env):\n c,url=env;s=c.get("/api/settings/subscription").json()["value"];s["default_format"]="base64";s["auto_detect"]=True;assert c.put("/api/settings/subscription",json={"value":s}).status_code==200\n r=c.get(url,headers={"user-agent":"mihomo/1.19"});assert r.headers["content-type"].startswith("application/yaml") and 'DARK AUTO' in r.text\n\ndef test_invalid_format_is_not_silently_substituted(env):\n c,url=env;assert c.get(url+"?format=singbox").status_code==400\n''')
print('Subscription V2 UI/test patch normalized')
